    "type": "trend-analysis",
    "audience": "analyst",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "Global Crude Oil Price Trends: A Historical Analysis (1970–2026)",
    "one_liner": "A comprehensive trend analysis of monthly crude oil prices spanning over five decades, identifying key price regimes, shocks, and long-term patterns.",
    "goal": "The reader should gain a thorough understanding of how crude oil prices have evolved from 1970 to 2026, identify the major price shocks and structural shifts driven by geopolitical and economic events, and be equipped with data-driven insights to contextualize future energy market movements.",
    "required_sections": [
      {
        "section_id": "executive-overview",
        "title": "Executive Overview",
        "objective": "Provide a high-level summary of the dataset scope, overall price trajectory, and the most critical findings from the analysis."
      },
      {
        "section_id": "long-term-trend",
        "title": "Long-Term Price Trajectory (1970–2026)",
        "objective": "Present the full time series of crude oil prices, highlighting the overall trend direction, major inflection points, and the magnitude of price changes across the entire period."
      },
      {
        "section_id": "decade-by-decade",
        "title": "Decade-by-Decade Breakdown",
        "objective": "Analyze average prices, volatility, and notable events within each decade (1970s, 1980s, 1990s, 2000s, 2010s, 2020s) to reveal how the pricing environment has shifted over time."
      },
      {
        "section_id": "volatility-and-shocks",
        "title": "Price Volatility & Major Shocks",
        "objective": "Identify and quantify periods of extreme price volatility, including the largest month-over-month and year-over-year changes, and correlate them with known geopolitical or economic events (e.g., oil embargoes, financial crises, pandemics)."
      },
      {
        "section_id": "statistical-summary",
        "title": "Statistical Summary & Distribution",
        "objective": "Provide descriptive statistics (mean, median, standard deviation, min, max, percentiles) and analyze the distribution of crude oil prices across the full dataset."
      },
      {
        "section_id": "outlook-and-conclusions",
        "title": "Outlook & Conclusions",
        "objective": "Summarize the key takeaways, discuss recent trends visible in the data (2020s), and offer concluding observations on the trajectory of global crude oil prices."
      }
    ],
    "kpis": [
      {
        "name": "Overall Price Range",
        "description": "The difference between the all-time maximum and minimum monthly crude oil prices across the dataset."
      },
      {
        "name": "Average Annual Growth Rate",
        "description": "The compound annual growth rate (CAGR) of crude oil prices from the first to the last observation in the dataset."
      },
      {
        "name": "Maximum Month-over-Month Change",
        "description": "The largest single-month absolute and percentage change in crude oil price, indicating peak short-term volatility."
      },
      {
        "name": "Decade with Highest Average Price",
        "description": "The decade that recorded the highest mean monthly crude oil price."
      },
      {
        "name": "Price Volatility (Standard Deviation)",
        "description": "The overall standard deviation of monthly crude oil prices, serving as a measure of long-term price dispersion."
      }
    ]
  }
}

