    font-size: 12px;
    color: var(--text-faint);
    letter-spacing: 0.04em;
  }
  .report-header .meta span { color: var(--text-muted); }
  /* Layout */
  .container { max-width: 1160px; margin: 0 auto; padding: 0 40px; }
  .section {
    padding: 52px 0 0;
  }
  .section:last-child { padding-bottom: 80px; }
