  }
  .kpi-card.accent { border-color: var(--accent); }
  .kpi-card.accent .kpi-value { color: var(--accent); }
  .kpi-card.green .kpi-value { color: var(--accent3); }
  .kpi-card.red .kpi-value { color: var(--accent2); }
  .kpi-card.gold .kpi-value { color: var(--accent4); }
  /* Chart containers */
  .chart-wrap {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 28px 24px;
    margin-bottom: 28px;
  }
  .chart-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 6px;
  }
  .chart-desc {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 20px;
    max-width: 700px;
  }
  /* Text content */
  .prose {
    color: var(--text-muted);
    font-size: 14px;
    line-height: 1.75;
    max-width: 820px;
    margin-bottom: 24px;
  }
