    color: var(--text-muted);
    max-width: 820px;
  }
  .callout strong { color: var(--text); }
  /* Two-col layout */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  /* Shock timeline */
  .shock-list { list-style: none; max-width: 860px; }
  .shock-list li {
    display: grid;
    grid-template-columns: 110px 1fr;
    gap: 16px;
