        { label: "GFC Peak\n$132.83", date: "2008-07", price: 132.83, side: 'left' },
        { label: "COVID Low\n$21.04", date: "2020-04", price: 21.04, side: 'right' },
        { label: "Ukraine\n$116.80", date: "2022-06", price: 116.80, side: 'left' },
      ];
      ctx.save();
      eventData.forEach(ev => {
        const xi = labels.indexOf(ev.date);
        if (xi < 0) return;
        const x = xScale.getPixelForValue(xi);
        const y = yScale.getPixelForValue(ev.price);
        // dot
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#e0b65c';
        ctx.fill();
        // line
        ctx.beginPath();
        ctx.strokeStyle = 'rgba(224,182,92,0.4)';
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        const yLabel = ev.side === 'right' ? y - 38 : y + 38;
        ctx.moveTo(x, y);
        ctx.lineTo(x, yLabel);
        ctx.stroke();
        ctx.setLineDash([]);
        // text
        ctx.fillStyle = '#e0b65c';
        ctx.font = '10px Segoe UI, sans-serif';
        ctx.textAlign = 'center';
        const lines = ev.label.split('\n');
        lines.forEach((line, i) => {
          const yT = ev.side === 'right' ? yLabel - (lines.length - 1 - i) * 12 - 4 : yLabel + i * 12 + 12;
          ctx.fillText(line, x, yT);
        });
      });
      ctx.restore();
    }
  }]
});

