function getAnnualAvg() {
  const byYear = {};
  rawData.forEach(([date, price]) => {
    const y = date.substring(0, 4);
    if (!byYear[y]) byYear[y] = [];
    byYear[y].push(price);
  });
  const years = Object.keys(byYear).sort();
  const avgs = years.map(y => {
    const arr = byYear[y];
    return +(arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(2);
  });
  return { years, avgs };
}

const { years: annualYears, avgs: annualAvgs } = getAnnualAvg();
