function buildHistogram(data, binSize) {
  const min = Math.floor(Math.min(...data) / binSize) * binSize;
  const max = Math.ceil(Math.max(...data) / binSize) * binSize;
  const bins = [];
  for (let b = min; b < max; b += binSize) {
    bins.push({ label: `$${b}–${b + binSize}`, lo: b, hi: b + binSize, count: 0 });
  }
  data.forEach(v => {
    const bin = bins.find(b => v >= b.lo && v < b.hi);
    if (bin) bin.count++;
  });
  return bins;
}
const histBins = buildHistogram(prices, 10);
